const intentRules:Array<{intent:AiConversationIntent;signals:string[];risk?:boolean}>=[
 {intent:"human_handoff",signals:["human","agent","person","staff","call me","talk to someone"]},
 {intent:"refund_review",signals:["refund","money back","payment dispute","charged twice","wrong charge"],risk:true},
 {intent:"funeral_memorial",signals:["funeral","memorial","cremation","ashes"]},
 {intent:"relocation",signals:["relocation","relocate","move my pet","pet transport documents"]},
 {intent:"booking_change",signals:["reschedule","change booking","cancel booking","change date","change time","cancel my booking","cancel my session","cancel my appointment","cancel my training","change my booking","change my session"]},
 // "When is my Meet & Greet and who is my trainer?" matched nothing and was handed to a human (staging, 26 Sep
 // 2026). Founder decision: a signed-in customer's questions about their own bookings get a read-only answer.
 {intent:"booking_status",signals:["booking status","where is my provider","provider status","eta","on the way","my next session","next session","when is my","who is my trainer","my trainer","my booking","my appointment","upcoming booking"]},
 {intent:"booking_create",signals:["book a","book grooming","make a booking","schedule a","need grooming","need a grooming","need a dog grooming","grooming slot","need training","need boarding","need sitting"]},
 {intent:"subscription_wallet",signals:["subscription","wallet","credits","balance","renewal"]},
 {intent:"coupon",signals:["coupon","promo","discount","offer code"]},
 {intent:"support",signals:["complaint","issue","problem","support","help","not happy"]},
 {intent:"service_info",signals:["price","pricing","service","package","what do you offer","availability","grooming","boarding","pet sitting","pet taxi","dog training"]},
];

/* Signals match whole words, plural included ("services", "packages"). Substring matching read "personal"
 * as "person" (an explicit request for a human) and "details" or "vegetarian" as "eta" (booking status),
 * so ordinary sentences paused the AI. */
const signalPatterns=new Map<string,RegExp>();
function hasSignal(text:string,signal:string){let pattern=signalPatterns.get(signal);if(!pattern){pattern=new RegExp(`(^|[^a-z0-9])${signal.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")}(e?s)?($|[^a-z0-9])`);signalPatterns.set(signal,pattern);}return pattern.test(text);}
export function classifyAiIntent(input:string):AiIntentDecision{
 const text=input.trim().toLowerCase();
 if(needsImmediateVetGuidance(text))return{intent:"human_handoff",confidence:1,confidenceBasis:"deterministic_emergency_routing",signals:["pet_emergency"],policyRisk:true};
 if(!text)return{intent:"unknown",confidence:0,confidenceBasis:"keyword_heuristic_sandbox",signals:[],policyRisk:false};
 const enquiry=policyEnquiryTopic(text);
 if(enquiry)return{intent:"service_info",confidence:0.9,confidenceBasis:"keyword_heuristic_sandbox",signals:[POLICY_INFORMATION_SIGNAL,enquiry],policyRisk:false};
 const matchedSignals=(rule:(typeof intentRules)[number])=>rule.signals.filter(signal=>hasSignal(rule.intent==="human_handoff"&&signal==="agent"?text.replace(/\b(?:ai|artificial intelligence|automated|virtual|bot)\s+agents?\b/g,"automated assistant"):text,signal));
 // Preserve a specific high-risk intent (for example refund/payment dispute) before the generic
 // forbidden-action fence, so Finance/CX routing remains precise while risky mixed service requests
 // are still blocked before ordinary service intent can win.
 for(const rule of intentRules.filter(rule=>rule.risk)){
  const matched=matchedSignals(rule);
  if(matched.length){const confidence=Math.min(0.98,0.82+Math.min(3,matched.length)*0.05);return{intent:rule.intent,confidence,confidenceBasis:"keyword_heuristic_sandbox",signals:matched,policyRisk:true};}
 }
 const quotePreparation=isVoiceSalesQuoteRequest(input),riskText=quotePreparation?voiceQuotePolicyText(text):text;
 const forbidden=(forbiddenAutonomousActions as readonly string[]).filter(action=>riskText.includes(action.replaceAll("_"," ")));
 if(forbidden.length)return{intent:"unknown",confidence:0.4,confidenceBasis:"keyword_heuristic_sandbox",signals:forbidden,policyRisk:true};
 // Catalogue/service evidence is required: isSalesInformationQuestion alone matches bare "pay"
 // account questions (AI-02), which must stay unknown for authenticated chat model-first routing.
 const catalogueService=/\b(?:grooming|boarding|sitting|training|taxi|food|walking|relocation|funeral|memorial)\b/.test(text);
 const readOnlyServiceInfo=catalogueService&&(isSalesInformationQuestion(input)||/\b(?:information|details?|pricing|prices?|costs?|packages?)\b/.test(text));
 if(readOnlyServiceInfo)return{intent:"service_info",confidence:0.9,confidenceBasis:"keyword_heuristic_sandbox",signals:["service_information_request"],policyRisk:false};
 for(const rule of intentRules){
  const matched=matchedSignals(rule);
  if(matched.length){const confidence=Math.min(0.98,0.82+Math.min(3,matched.length)*0.05);return{intent:rule.intent,confidence,confidenceBasis:"keyword_heuristic_sandbox",signals:matched,policyRisk:Boolean(rule.risk)};}
 }
 if(quotePreparation&&!detectPromptInjection(input).blocked)return{intent:"booking_create",confidence:0.9,confidenceBasis:"keyword_heuristic_sandbox",signals:["quote_preparation"],policyRisk:false};
 return{intent:"unknown",confidence:0.25,confidenceBasis:"keyword_heuristic_sandbox",signals:[],policyRisk:false};
}

