async function sessionForThread(db:D1Database,threadId:string,customerId:string,provider:AiResponseProvider){const existing=await db.prepare("SELECT id,status,customer_id,provider,provider_status,model_ref FROM ai_conversation_sessions WHERE thread_id=?").bind(threadId).first<Row>();const now=Date.now();if(existing){if(String(existing.customer_id)!==customerId)throw new Error("AI conversation session belongs to a different customer");
 // The session is rewritten only when the provider serving it changed; the turn's own batch records its status.
 if(String(existing.provider??"")!==provider.provider||String(existing.provider_status??"")!==provider.status||String(existing.model_ref??"")!==String(provider.modelRef??""))await db.prepare("UPDATE ai_conversation_sessions SET provider=?,provider_status=?,model_ref=?,updated_at=? WHERE id=?").bind(provider.provider,provider.status,provider.modelRef,now,String(existing.id)).run();return{id:String(existing.id),status:String(existing.status)};}const id=`AISES-${crypto.randomUUID().slice(0,12).toUpperCase()}`;await db.prepare("INSERT INTO ai_conversation_sessions (id,thread_id,customer_id,status,provider,provider_status,model_ref,created_at,updated_at) VALUES (?,?,?,'ai_active',?,?,?,?,?)").bind(id,threadId,customerId,provider.provider,provider.status,provider.modelRef,now,now).run();return{id,status:"ai_active"};}
