const ENTERPRISE_OBJECTION=/\b(enterprise|corporate|procurement|bulk contract|fleet|multi-location contract|business account)\b/i;
async function aiLeadLowConfidenceDecision(db:D1Database,threadId:string,message:string){
 const thread=await db.prepare("SELECT lead_id FROM communication_threads WHERE id=?").bind(threadId).first<Row>();const leadId=text(thread?.lead_id);if(!leadId)return{leadId:null,clarify:false,escalate:true,enterprise:false,count:0,max:0};
 const ownership=await db.prepare("SELECT * FROM ai_lead_ownership WHERE lead_id=? AND status='ai_owned'").bind(leadId).first<Row>();if(!ownership)return{leadId,clarify:false,escalate:true,enterprise:false,count:0,max:0};
 const enterprise=ENTERPRISE_OBJECTION.test(message);if(enterprise){await db.prepare("UPDATE ai_lead_ownership SET enterprise_objection=1,escalation_reason='high_value_enterprise_objection',updated_at=? WHERE lead_id=? AND status='ai_owned'").bind(Date.now(),leadId).run();return{leadId,clarify:false,escalate:true,enterprise:true,count:Number(ownership.clarification_count||0),max:Number(ownership.max_clarifications||2)};}
 const max=Math.max(1,Number(ownership.max_clarifications||2)),next=Number(ownership.clarification_count||0)+1;await db.prepare("UPDATE ai_lead_ownership SET clarification_count=?,updated_at=? WHERE lead_id=? AND status='ai_owned'").bind(next,Date.now(),leadId).run();return{leadId,clarify:next<max,escalate:next>=max,enterprise:false,count:next,max};
