type Row=Record<string,unknown>;
const text=(value:unknown)=>String(value??"").trim();
export type AiConversationChannel="whatsapp"|"chat"|"voice";
export type AiConversationIntent="service_info"|"booking_create"|"booking_status"|"booking_change"|"subscription_wallet"|"coupon"|"support"|"refund_review"|"funeral_memorial"|"relocation"|"human_handoff"|"unknown";
/** Intent confidence is a deterministic keyword-match heuristic (sandbox), NOT a model probability.
 *  Every surface showing this number must label it as such. */
export type AiIntentDecision={intent:AiConversationIntent;confidence:number;confidenceBasis:"keyword_heuristic_sandbox"|"service_scoped_dialogue"|"deterministic_emergency_routing"|"bounded_refund_booking_followup";signals:string[];policyRisk:boolean};
export type AiProviderInput={threadId:string;customerId:string;channel:AiConversationChannel;inputText:string;intent:AiIntentDecision;context:Record<string,unknown>;onDelta?:(delta:string)=>void;signal?:AbortSignal};
export type AiActionRequest={toolCode:AiToolCode;arguments:Record<string,unknown>};
export type AiProviderResult={text:string;provider:string;modelRef:string|null;latencyMs:number;inputTokens?:number;outputTokens?:number;costMinor?:number;confidence?:number;unsupported?:boolean;failure?:string;
 /** The provider's HTTP status when it answered with an error; diagnostics only. */
 failureStatus?:number;groundingRefs?:string[];referencedCustomerIds?:string[];highImpactAction?:boolean;actionRequests?:AiActionRequest[];
 /** Every amount the reply quotes is a price in the server-owned catalogue supplied for this turn. */
