async function generateWithDeadline(provider:AiResponseProvider,input:AiProviderInput){
 const deadlineMs=Math.min(125_000,Math.max(1,Number(provider.deadlineMs??125_000)));
 let timer:ReturnType<typeof setTimeout>|undefined;
 try{return await Promise.race([provider.generate(input),new Promise<never>((_,reject)=>{timer=setTimeout(()=>reject(Object.assign(new Error("AI provider deadline exceeded"),{name:"TimeoutError"})),deadlineMs);})]);}
 finally{if(timer)clearTimeout(timer);}
}

export function isExplicitCustomerActionConfirmation(message:string){
 const value=text(message).toLowerCase().replace(/\s+/g," ");
 if(!value||/\b(no|not|don\'t|do not|stop|cancel that|wait)\b/.test(value))return false;
 return /^(yes|yes please|confirm|confirmed|go ahead|proceed|book it|book this|reserve it|reserve this|pay|create the payment|send the payment|yes,? go ahead|yes,? proceed)([.! ]*)$/.test(value)
  || /\b(yes|confirm|go ahead|proceed)\b.{0,32}\b(book|booking|reserve|slot|payment|pay|reschedule|cancel)\b/.test(value)
  || /\b(book|reserve|reschedule|cancel)\b.{0,32}\b(yes|confirm|go ahead|proceed)\b/.test(value);
}
function actionResultValue(value:unknown,keys:string[]):string{
 if(!value||typeof value!=="object")return"";
 for(const key of keys){const candidate=(value as Row)[key];if(typeof candidate==="string"&&candidate.trim())return candidate.trim();}
 for(const nested of Object.values(value as Row)){if(nested&&typeof nested==="object"){const found=actionResultValue(nested,keys);if(found)return found;}}
 return"";
}
