async function verifiedGroundingRefs(db:D1Database,references:unknown){
 const requested=[...new Set((Array.isArray(references)?references:[]).filter((item):item is string=>typeof item==="string"&&item.trim().length>0).map(item=>item.trim()))];
 if(!requested.length)return{references:[] as string[],verified:false};
 const now=Date.now(),verified:string[]=[];
 try{for(const reference of requested){const row=await db.prepare("SELECT visibility_scope_json FROM ai_knowledge_source_versions WHERE (id=? OR immutable_hash=?) AND status='active' AND (effective_from IS NULL OR effective_from<=?) AND (effective_to IS NULL OR effective_to>=?)").bind(reference,reference,now,now).first<Row>();if(!row)continue;let scopes:string[]=[];try{const parsed=JSON.parse(String(row.visibility_scope_json||"[]"));if(Array.isArray(parsed))scopes=parsed.filter((item):item is string=>typeof item==="string").map(item=>item.toLowerCase());}catch{}if(scopes.includes("public"))verified.push(reference);}}
 catch{return{references:[] as string[],verified:false};}
 return{references:verified,verified:verified.length===requested.length};
}

