type Row=Record<string,unknown>;
export type PublicAiWebHistoryTurn={role:"user"|"assistant";text:string};
const text=(value:unknown)=>String(value??"").trim();
const STOP_WORDS=new Set(["a","an","and","are","can","do","does","for","how","i","in","is","me","of","on","the","to","what","which","with","you"]);
function searchTerms(value:string){return Array.from(new Set(value.toLowerCase().match(/[a-z0-9]+/g)||[])).filter(term=>term.length>1&&!STOP_WORDS.has(term));}
/**
 * Public history is browser-supplied and unauthenticated. An "assistant" turn in it can be fabricated to
 * put words or instructions in PawSpace AI's mouth, so only the visitor's own prior questions are kept,
 * trust-safety redacted like the live question, and passed to the model as untrusted context.
 */
function publicHistory(value:unknown):PublicAiWebHistoryTurn[]{if(!Array.isArray(value))return[];return value.slice(-8).flatMap(item=>{if(!item||typeof item!=="object"||Array.isArray(item))return[];const row=item as Row,role=text(row.role),body=text(row.text).slice(0,800);return role==="user"&&body?[{role:"user",text:redactTrustSafetyText(body).redacted} as PublicAiWebHistoryTurn]:[];});}

export async function ensureAiWebChatTables(db:D1Database){return ensureD1Once(db,"ai_web_chat_tables",async()=>{await ensureCommunicationTables(db);await db.batch([
 db.prepare("CREATE TABLE IF NOT EXISTS ai_web_leads (id TEXT PRIMARY KEY,session_key TEXT NOT NULL UNIQUE,name TEXT,email TEXT,phone TEXT,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'new',created_at INTEGER NOT NULL)"),
 db.prepare("CREATE TABLE IF NOT EXISTS ai_web_chat_events (id TEXT PRIMARY KEY,thread_id TEXT,customer_id TEXT,event_type TEXT NOT NULL,actor_ref TEXT NOT NULL,detail_json TEXT NOT NULL DEFAULT '{}',created_at INTEGER NOT NULL)"),
]);});}

export async function publicAiWebKnowledge(db:D1Database,input:{query:string}){await ensureAiWebChatTables(db);const query=text(input.query).toLowerCase(),terms=searchTerms(query);if(!query||!terms.length)return{mode:"public",knowledge:[],customerDataAccess:false,toolExecution:false};await ensureAiBusinessConfiguration(db);const rows=await db.prepare("SELECT id,title,content_text,visibility_scope_json,immutable_hash FROM ai_knowledge_source_versions WHERE status='active' AND (effective_from IS NULL OR effective_from<=?) AND (effective_to IS NULL OR effective_to>?) ORDER BY version DESC LIMIT 100").bind(Date.now(),Date.now()).all<Row>();const knowledge=rows.results.filter(row=>{try{const scope=JSON.parse(text(row.visibility_scope_json)||"[]")as string[];return scope.includes("public")}catch{return false}}).map(row=>{const title=text(row.title).toLowerCase(),content=text(row.content_text).toLowerCase(),combined=`${title} ${content}`;let score=combined.includes(query)?100:0;for(const term of terms){if(title.includes(term))score+=5;if(content.includes(term))score+=2;}return{row,score};}).filter(item=>item.score>0).sort((a,b)=>b.score-a.score).slice(0,5).map(({row})=>({id:text(row.id),title:text(row.title),excerpt:text(row.content_text).slice(0,600),immutableHash:text(row.immutable_hash)}));return{mode:"public",knowledge,customerDataAccess:false,toolExecution:false};}

type PublicServiceEntry={code:string;name:string;group:string;enabled:boolean};
/**
 * Public, unauthenticated view of the service directory. Operator-entered disabled reasons are internal
 * audit text and are never included. A failed service-control read degrades to an empty directory so the
 * public chat keeps its grounded/provider path instead of rejecting every request.
 */
/** Reads the public service directory. A failed read falls back to the pre-directory chat path and is recorded as a degraded turn, never passed off as an empty catalogue. */
async function publicServiceDirectory(db:D1Database,sessionKey:string):Promise<PublicServiceEntry[]>{const degradation=createDegradationLog();const directory=await listServiceControls(db).then(rows=>rows.map(service=>({code:service.code,name:service.name,group:service.group,enabled:service.enabled})),error=>degradation.note("service_controls",error,[] as PublicServiceEntry[]));if(degradation.degraded())await db.prepare("INSERT INTO ai_web_chat_events (id,thread_id,customer_id,event_type,actor_ref,detail_json,created_at) VALUES (?,NULL,NULL,'service_directory_degraded',?,?,?)").bind(crypto.randomUUID(),`public:${sessionKey}`,JSON.stringify({degraded:degradation.entries()}),Date.now()).run().catch(()=>undefined);return directory;}
const phrase=(value:string)=>` ${value.toLowerCase().replace(/[^a-z0-9]+/g," ").trim()} `;
/** The phrases a question may use to name a directory service, longest first. */
const serviceAliases=(service:PublicServiceEntry)=>[service.code.replaceAll("_"," "),service.name,...(service.code==="relocation"?["relocation"]:[])].map(phrase).filter(alias=>alias.trim()).sort((a,b)=>b.length-a.length);
/** Returns the service only when the question names exactly one distinct service; multi-service questions go to the general path. */
function matchPublicService(directory:PublicServiceEntry[],question:string){const q=phrase(question);const matches=directory.filter(service=>serviceAliases(service).some(alias=>q.includes(alias)));return matches.length===1?matches[0]:null;}
/** Words that only ask whether a service is offered: "Do you do boarding?", "Boarding?", "is grooming available". */
const AVAILABILITY_WORDS=new Set(["a","an","any","are","available","availability","can","currently","do","does","get","got","guys","have","has","hello","hey","hi","i","is","now","offer","offered","offering","offers","ok","okay","pawspace","please","pls","provide","provided","provides","providing","service","services","still","the","there","u","we","yes","you","your"]);
/**
 * The directory only knows whether a service is offered, so it answers only a bare service question: the
 * service's name and availability words, nothing else. What a service includes, care advice or a
 * comparison is a real question for the model.
 */
function isBareServiceQuestion(service:PublicServiceEntry,question:string){let rest=phrase(question);for(const alias of serviceAliases(service))while(rest.includes(alias))rest=rest.replace(alias," ");return rest.trim().split(" ").filter(Boolean).every(word=>AVAILABILITY_WORDS.has(word));}
const DETAIL_QUESTION=/\b(includ\w*|inclusions?|cover(?:s|ed)?|comes? with|details?)\b/i;
/**
 * The directory's own answer. Asked what a service includes, it gives the approved public knowledge
 * written for that service (its title names the service) when there is any - the directory itself holds
 * only names and availability, so nothing beyond those records is ever stated.
 */
function directoryAnswer(service:PublicServiceEntry,question:string,knowledge:Array<{title:string;excerpt:string}>){
 if(!service.enabled)return`${service.name} is temporarily unavailable on PawSpace.`;
 const offered=`PawSpace offers ${service.name}. I can help you understand the service or start from the ${service.name} section in PawSpace.`;
 if(isBareServiceQuestion(service,question))return`Yes. ${offered}`;
 const aliases=serviceAliases(service),approved=DETAIL_QUESTION.test(question)?knowledge.find(item=>item.excerpt&&aliases.some(alias=>phrase(item.title).includes(alias))):undefined;
 return approved?`PawSpace offers ${service.name}. From PawSpace's approved information: ${approved.excerpt}`:offered;
}

const PRICE_QUESTION=/\b(price|prices|pricing|cost|costs|fee|fees|charge|charges|package|packages|plan|plans|how much|rate|rates)\b/i;
/** Only a plain catalogue/price lookup may bypass conversation. A price word inside a care,
 * subscription, package-detail or budget question must not erase the rest of the customer's intent. */
const PRICE_LOOKUP_WORDS=new Set([...AVAILABILITY_WORDS,"what","whats","which","how","much","price","prices","pricing","cost","costs","fee","fees","charge","charges","package","packages","plan","plans","rate","rates","for","of","does","list","show","me","tell","about","and","they"]);
function isPlainPriceLookup(service:PublicServiceEntry,question:string){let rest=phrase(question);for(const alias of serviceAliases(service))while(rest.includes(alias))rest=rest.replace(alias," ");return rest.trim().split(" ").filter(Boolean).every(word=>PRICE_LOOKUP_WORDS.has(word));}

const inr=(value:unknown)=>`₹${Number(value).toLocaleString("en-IN")}`;
/**
 * A Training price or package question is answered from the governed Training catalogue itself, the same
 * rows the booking quote prices from, so the assistant can never quote a price the booking will not charge.
 * Staging (26 Sep 2026) answered "PawSpace offers Training…" with no packages or prices at all.
 */
async function trainingCatalogueAnswer(db:D1Database){const packages=await listTrainingPackages(db).catch(()=>[] as Row[]);if(!packages.length)return null;const programme=packages.find(item=>!Number(item.meet_and_greet)),extra=Number(programme?.extra_pet_percent??DEFAULT_EXTRA_PET_PERCENT);const lines=packages.map(item=>Number(item.meet_and_greet)?`• ${text(item.name)}: one home visit to meet a trainer, ${inr(item.base_price)}, paid in full`:`• ${text(item.name)}: ${Number(item.sessions)} sessions within ${Number(item.validity_days)} days, ${inr(item.base_price)}`);return`PawSpace Dog Training plans (prices are for one dog; each extra dog adds ${extra}% of the plan price):\n${lines.join("\n")}\nProgrammes can be paid in full or 50% upfront. Open the Training section to choose a plan, a trainer and your dates.`;}

const PUBLISHED_PRICE_QUESTION=/\b(price|prices|pricing|cost|costs|charge|charges|rate|rates|fee|fees|how much)\b|₹|\brs\.?\s*\d/i;
/** Owner decision: the assistant may quote published prices as "from Rs X", never a final amount. */
async function publishedPriceAnswer(db:D1Database,service:PublicServiceEntry){
 // One table per service: a missing table for another vertical must not hide this service's prices.
 const sql=({
  grooming:"SELECT MIN(base_price) price FROM service_packages WHERE service_code='grooming' AND active=1 AND instr(package_code,'__')=0",
  dog_training:"SELECT MIN(base_price) price FROM training_commercial_packages WHERE active=1",
  boarding:"SELECT MIN(base_price_per_pet) price FROM boarding_commercial_packages WHERE active=1",
  pet_sitting:"SELECT MIN(base_price_per_pet) price FROM sitting_commercial_packages WHERE active=1",
  dog_walking:"SELECT MIN(amount_per_walk) price FROM walking_commercial_packages WHERE active=1",
 } as Record<string,string>)[service.code];
 if(!sql)return null;
 const row=await db.prepare(sql).first<Record<string,unknown>>().catch(()=>null),price=Number(row?.price);
 if(!Number.isFinite(price)||price<=0)return null;
 const from=new Intl.NumberFormat("en-IN",{style:"currency",currency:"INR",maximumFractionDigits:0}).format(price);
 return`${service.name} starts from ${from} for one pet. The final price depends on the package, date and time, and is confirmed at checkout.`;
}

export async function runPublicAiWebChat(db:D1Database,input:{query:string;history?:unknown;sessionKey?:string;careContext?:AtlasCareContext;cityId?:string|null;zoneId?:string|null}){
 if(needsImmediateVetGuidance(input.query))return{...emergencyChatResponse(input.sessionKey),knowledge:[],serviceDirectory:[],trustSafetyRedacted:false};
 await ensureAiWebChatTables(db);
 const query=text(input.query).slice(0,4000);if(!query)throw new Response("Question is required",{status:400});
 const sessionKey=text(input.sessionKey).slice(0,120)||crypto.randomUUID(),now=Date.now();
 const inspected=await inspectTrustSafetyText(db,{text:query,channel:"chat",sourceReference:`ai-web-public-turn:${sessionKey}:${now}`,actorType:"customer",actorId:`public:${sessionKey}`,detail:{surface:"public_ai_web_chat"},asOf:now});
 const grounded=await publicAiWebKnowledge(db,{query:inspected.redacted}),history=publicHistory(input.history);
 const serviceDirectory=await publicServiceDirectory(db,sessionKey);
 const careContext=atlasCareContext(input.careContext),couponRequested=customerRequestedCoupon(query);
 const matchedService=matchPublicService(serviceDirectory,inspected.redacted)||serviceDirectory.find(service=>service.code===careContext?.serviceCode)||null;
 const subscriptionQuestion=/\b(subscriptions?|packs?|credits?)\b/i.test(inspected.redacted)&&matchedService?.code==="grooming";
 const subscriptions=subscriptionQuestion&&matchedService?.enabled?await publicGroomingSubscriptionCatalogue(db,{cityId:input.cityId,zoneId:input.zoneId,species:careContext?.species}):null;
 if(subscriptions&&subscriptions.status!=="published"){
  const output=subscriptions.status==="location_required"?"Choose the service city and zone in Grooming so I can check the published subscription plans and prices.":"I cannot verify a published grooming subscription plan for this location right now. Please check the Grooming section before choosing a plan; I cannot confirm prices, credits or payment terms.";
  await db.prepare("INSERT INTO ai_web_chat_events (id,thread_id,customer_id,event_type,actor_ref,detail_json,created_at) VALUES (?,NULL,NULL,'public_turn',?,?,?)").bind(crypto.randomUUID(),`public:${sessionKey}`,JSON.stringify({outcome:"subscription_catalogue_missing",catalogueStatus:subscriptions.status,customerDataAccess:false,toolExecution:false}),now).run().catch(()=>{console.error("ai-web-chat: subscription catalogue event write failed");});
  return{...grounded,serviceDirectory,sessionKey,ai:{providerConnected:false,turn:{output,provider:"canonical_subscription_catalogue",modelRef:null,outcome:"reply_ready",handoffReason:null}},customerDataAccess:false,toolExecution:false,autonomousExecution:false,trustSafetyRedacted:inspected.detected};
 }
 const directoryReply=async(service:PublicServiceEntry,providerFailure?:string)=>{
  const subscriptionFallback=subscriptions?.status==="published"?`Published grooming subscription plans for the selected location:\n${subscriptions.plans.map(plan=>`• ${String(plan.name)}: ${String(plan.currency)} ${Number(plan.price)}, ${Number(plan.sessions)} credits within ${Number(plan.validityValue)} ${String(plan.validityUnit)}; ${String(plan.servicePackageCode)}, ${Number(plan.creditsPerPet)} credit(s) per pet.`).join("\n")}\nThese are plan prices, not a pay-as-you-go tariff or verified wallet balance. Check species eligibility and the published payment terms in Grooming before choosing a plan.`:null;
  const output=careReplyWithoutUnrequestedOffers(subscriptionFallback||directoryAnswer(service,inspected.redacted,grounded.knowledge),couponRequested);
  await db.prepare("INSERT INTO ai_web_chat_events (id,thread_id,customer_id,event_type,actor_ref,detail_json,created_at) VALUES (?,NULL,NULL,'public_turn',?,?,?)").bind(crypto.randomUUID(),`public:${sessionKey}`,JSON.stringify({outcome:"canonical_service_answer",providerConnected:false,...(providerFailure?{providerFailure}:{}),serviceCode:service.code,serviceEnabled:service.enabled,customerDataAccess:false,toolExecution:false,trustSafetyRedacted:inspected.detected}),now).run().catch(error=>{if(!subscriptions)throw error;console.error("ai-web-chat: subscription catalogue event write failed");});
  return{...grounded,serviceDirectory,sessionKey,ai:{providerConnected:false,turn:{output,provider:"canonical_service_directory",modelRef:null,outcome:"reply_ready",handoffReason:null}},customerDataAccess:false,toolExecution:false,autonomousExecution:false,trustSafetyRedacted:inspected.detected};
 };
 /* The directory answers "is it offered?". Every question naming a service used to stop here, so "what is
  * included in boarding?" or a question about an anxious dog's stay got the same one-liner and the model
  * never saw it. Now only a bare service question does; anything more goes to the model below, grounded
  * like every other question, and the directory answer is its fallback when no provider answers. */
 if(matchedService){
  // A Training price or package question is answered from the governed Training catalogue, before the model.
  const catalogueAnswer=matchedService.enabled&&matchedService.code==="dog_training"&&PRICE_QUESTION.test(inspected.redacted)&&isPlainPriceLookup(matchedService,inspected.redacted.replace(/\bin (?:bengaluru|bangalore)\b/gi," "))?await trainingCatalogueAnswer(db):null;
  if(catalogueAnswer){
   await db.prepare("INSERT INTO ai_web_chat_events (id,thread_id,customer_id,event_type,actor_ref,detail_json,created_at) VALUES (?,NULL,NULL,'public_turn',?,?,?)").bind(crypto.randomUUID(),`public:${sessionKey}`,JSON.stringify({outcome:"canonical_training_catalogue_answer",providerConnected:false,serviceCode:matchedService.code,serviceEnabled:matchedService.enabled,customerDataAccess:false,toolExecution:false,trustSafetyRedacted:inspected.detected}),now).run();
   return{...grounded,serviceDirectory,sessionKey,ai:{providerConnected:false,turn:{output:catalogueAnswer,provider:"canonical_training_catalogue",modelRef:null,outcome:"reply_ready",handoffReason:null}},customerDataAccess:false,toolExecution:false,autonomousExecution:false,trustSafetyRedacted:inspected.detected};
  }
  // Owner decision: other services quote their published "from" price, from the same tables the booking prices from.
  const priceAnswer=matchedService.enabled&&matchedService.code!=="dog_training"&&PUBLISHED_PRICE_QUESTION.test(inspected.redacted)&&isPlainPriceLookup(matchedService,inspected.redacted)?await publishedPriceAnswer(db,matchedService).catch(()=>null):null;
  if(priceAnswer){
   await db.prepare("INSERT INTO ai_web_chat_events (id,thread_id,customer_id,event_type,actor_ref,detail_json,created_at) VALUES (?,NULL,NULL,'public_turn',?,?,?)").bind(crypto.randomUUID(),`public:${sessionKey}`,JSON.stringify({outcome:"canonical_service_answer",providerConnected:false,serviceCode:matchedService.code,serviceEnabled:matchedService.enabled,customerDataAccess:false,toolExecution:false,trustSafetyRedacted:inspected.detected}),now).run();
   return{...grounded,serviceDirectory,sessionKey,ai:{providerConnected:false,turn:{output:priceAnswer,provider:"canonical_service_directory",modelRef:null,outcome:"reply_ready",handoffReason:null}},customerDataAccess:false,toolExecution:false,autonomousExecution:false,trustSafetyRedacted:inspected.detected};
  }
  if(isBareServiceQuestion(matchedService,inspected.redacted))return directoryReply(matchedService);
  // No provider configured: the directory answers as it always did, without the reads a model call needs.
  if(!(await aiProviderConnection("chat")).connected)return directoryReply(matchedService,"not_configured");
 }
 // A named service is grounding in its own right (directory and catalogue), so it does not need a knowledge match.
 if(!grounded.knowledge.length&&!matchedService){
  const enabledServices=serviceDirectory.filter(service=>service.enabled).map(service=>service.name).join(", ");
