 try{rows=(await db.prepare(`SELECT o.id offer_id,o.thread_id,o.customer_id,b.id booking_id,b.package_name FROM voice_sales_offers o JOIN booking_payments p ON p.booking_id=json_extract(o.result_json,'$.bookingId') JOIN canonical_bookings b ON b.id=p.booking_id WHERE o.status='completed' AND p.status='captured' AND o.completed_at>=? ${input.threadId?"AND o.thread_id=?":""} AND NOT EXISTS (SELECT 1 FROM ai_web_chat_events e WHERE e.id='ai-booking-paid:'||o.id) ORDER BY o.completed_at LIMIT ?`).bind(...(input.threadId?[asOf-7*86400000,input.threadId,limit]:[asOf-7*86400000,limit])).all<Row>()).results;}
 catch(error){if(/no such table/i.test(String((error as Error)?.message)))return{announced:0};throw error;}
 let announced=0;
 for(const row of rows){
  const threadId=text(row.thread_id),customerId=text(row.customer_id),offerId=text(row.offer_id);
  // Claimed first, so a chat read and the sweep never both announce the same payment.
  const claim=await db.prepare("INSERT OR IGNORE INTO ai_web_chat_events (id,thread_id,customer_id,event_type,actor_ref,detail_json,created_at) VALUES (?,?,?,'ai_booking_paid','ai-sales-offer',?,?)").bind(`ai-booking-paid:${offerId}`,threadId,customerId,JSON.stringify({offerId,bookingId:text(row.booking_id)}),asOf).run();
  if(Number(claim.meta?.changes)!==1)continue;
  const message=`Payment received - your ${text(row.package_name)||"PawSpace"} booking is confirmed. Thank you! You can see it any time under Your bookings.`;
  // A send that fails releases the claim, so the next chat read or sweep tries again.
  const release=()=>db.prepare("DELETE FROM ai_web_chat_events WHERE id=?").bind(`ai-booking-paid:${offerId}`).run();
  try{
   const inbound=await db.prepare("SELECT channel,provider FROM communication_messages WHERE thread_id=? AND direction='inbound' ORDER BY created_at DESC LIMIT 1").bind(threadId).first<Row>();
   if(text(inbound?.channel)==="whatsapp"){
    // The same transport rule as a live WhatsApp turn: an unknown provider is the sandbox simulator.
    const{queueWhatsAppUatOutbound,whatsappUatProviders}=await import("./whatsapp-uat-adapter");const value=text(inbound?.provider),provider=(whatsappUatProviders as readonly string[]).includes(value)?value as (typeof whatsappUatProviders)[number]:"sandbox_simulator";
    const queued=await queueWhatsAppUatOutbound(db,{provider,threadId,customerId,text:message,idempotencyKey:`ai-booking-paid:${offerId}`,createdBy:"ai-sales-offer",now:asOf});
    if(!queued.queued){await release();continue;}
   }else await postBotMessage(db,{threadId,customerId,reply:{text:message,choices:[],inputHint:null},idempotencyKey:`ai-booking-paid:${offerId}`});
  }catch{await release().catch(()=>undefined);continue;}
  announced++;
 }
 return{announced};
}

async function postBotMessage(db:D1Database,input:{threadId:string;customerId:string;reply:BotReply;idempotencyKey:string}){
 const now=Date.now();
 // Message and thread touch go in one D1 round trip.
 await db.batch([
  db.prepare("INSERT OR IGNORE INTO communication_messages (id,thread_id,customer_id,booking_id,lead_id,ticket_id,direction,channel,purpose,template_key,payload_json,status,provider,provider_reference,idempotency_key,policy_json,created_by,created_at,updated_at) VALUES (?,?,?,NULL,NULL,NULL,'outbound','chat','service',?,?,'delivered','pawspace_bot',NULL,?,?,'web-chat-bot',?,?)")
  .bind(`MSG-BOT-${crypto.randomUUID().slice(0,12).toUpperCase()}`,input.threadId,input.customerId,WEB_CHAT_BOT_TEMPLATE_KEY,JSON.stringify({text:input.reply.text,choices:input.reply.choices,inputHint:input.reply.inputHint}),input.idempotencyKey,JSON.stringify({channel:"chat",externalDelivery:false,productionDelivery:false,deterministicBot:true}),now,now),
  db.prepare("UPDATE communication_threads SET updated_at=? WHERE id=?").bind(now,input.threadId),
 ]);
}

async function recordCustomerMessage(db:D1Database,input:{actor:AuthenticatedActor;customerId:string;text:string;idempotencyKey:string;callbackContext?:Extract<BotEvent,{type:"call"}>&{message:string};pendingHandoff?:{reason:AiHandoffReason;reply:BotReply;path:"human"|"completed"}}){
 const threadId=await openThread(db,input.customerId),messageId=`MSG-CHAT-${crypto.randomUUID().slice(0,12).toUpperCase()}`,now=Date.now();
 const inspected=await inspectTrustSafetyText(db,{text:input.text,channel:"chat",sourceReference:`ai-web-bot:${input.idempotencyKey}`,actorType:"customer",actorId:input.actor.email,customerId:input.customerId,threadId,messageId,asOf:now,detail:{surface:"web_chat_bot"}});
 await db.batch([db.prepare("INSERT INTO communication_messages (id,thread_id,customer_id,booking_id,lead_id,ticket_id,direction,channel,purpose,template_key,payload_json,status,provider,provider_reference,idempotency_key,policy_json,created_by,created_at,updated_at) VALUES (?,?,?,NULL,NULL,NULL,'inbound','chat','transactional','web_app_chat',?,'received','pawspace_web',NULL,?,?,?,?,?)").bind(messageId,threadId,input.customerId,JSON.stringify({text:inspected.redacted,safetyRedacted:inspected.detected,...(input.callbackContext?{callbackContext:input.callbackContext}:{}),...(input.pendingHandoff?{pendingHandoff:input.pendingHandoff}:{})}),input.idempotencyKey,JSON.stringify({authenticated:true,customerOwned:true,externalDelivery:false,trustSafetyInspected:true,bot:true}),input.actor.email,now,now),db.prepare("UPDATE communication_threads SET status=CASE WHEN status='pending_customer' THEN 'open' ELSE status END,updated_at=? WHERE id=?").bind(now,threadId)]);
 return{threadId,messageId};
}

/** The bot's opening message for a signed-in customer with no conversation yet, or one restarting. */
export async function startCustomerWebChatBot(db:D1Database,input:{actor:AuthenticatedActor;customerId:string}){
 await ensureAiWebChatTables(db);await requireCustomerOwnership(db,input.actor,input.customerId);
 const existing=await currentWebChatThread(db,input.customerId);
 if(existing){const any=await db.prepare("SELECT id FROM communication_messages WHERE thread_id=? LIMIT 1").bind(existing).first<Row>();if(any)return{threadId:existing,started:false};}
